// Font registry (copy of the film's lib/fonts.mjs list; files are read from mcr-2026-sponzori/fonts/, latin + latin-ext woff2).
// A sponsor module may add families with `export const fonts = { Name: { v|s|vi|si … } }` (files must be in mcr-2026-sponzori/fonts/
// or in mcr-2026-bannery/assets/fonts/ — set `dir: 'bannery'`). Sponsor agents: do not edit this file.
import fs from 'node:fs';
import path from 'node:path';
import { FILM, ROOT } from './util.mjs';

const LATIN = 'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD';
const EXT = 'U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF';

export const FONTS = {
  Archivo: { v: 'archivo-{r}-wdth-normal', weight: '100 900', stretch: '62% 125%' },
  'Bricolage Grotesque': { v: 'bricolage-grotesque-{r}-wdth-normal', weight: '200 800', stretch: '75% 100%' },
  Inter: { v: 'inter-{r}-wght-normal', weight: '100 900' },
  'Inter Tight': { v: 'inter-tight-{r}-wght-normal', weight: '100 900' },
  Montserrat: { v: 'montserrat-{r}-wght-normal', vi: 'montserrat-{r}-wght-italic', weight: '100 900' },
  Bitter: { v: 'bitter-{r}-wght-normal', vi: 'bitter-{r}-wght-italic', weight: '100 900' },
  Nunito: { v: 'nunito-{r}-wght-normal', vi: 'nunito-{r}-wght-italic', weight: '200 1000' },
  Unbounded: { v: 'unbounded-{r}-wght-normal', weight: '200 900' },
  Oswald: { v: 'oswald-{r}-wght-normal', weight: '200 700' },
  Outfit: { v: 'outfit-{r}-wght-normal', weight: '100 900' },
  'Space Grotesk': { v: 'space-grotesk-{r}-wght-normal', weight: '300 700' },
  Anton: { s: { 400: 'anton-{r}-400-normal' } },
  Poppins: { s: { 400: 'poppins-{r}-400-normal', 600: 'poppins-{r}-600-normal', 800: 'poppins-{r}-800-normal', 900: 'poppins-{r}-900-normal' } },
  'Playfair Display': { s: { 700: 'playfair-display-{r}-700-normal', 900: 'playfair-display-{r}-900-normal' }, si: { 700: 'playfair-display-{r}-700-italic', 900: 'playfair-display-{r}-900-italic' } },
  'Cormorant Garamond': { v: 'cormorant-garamond-{r}-wght-normal', vi: 'cormorant-garamond-{r}-wght-italic', weight: '300 700' },
  Jost: { v: 'jost-{r}-wght-normal', vi: 'jost-{r}-wght-italic', weight: '100 900' },
  Saira: { v: 'saira-{r}-wdth-normal', weight: '100 900', stretch: '50% 125%' },
  'Saira Extra Condensed': { s: { 400: 'saira-extra-condensed-{r}-400-normal', 700: 'saira-extra-condensed-{r}-700-normal', 800: 'saira-extra-condensed-{r}-800-normal', 900: 'saira-extra-condensed-{r}-900-normal' } },
  'Exo 2': { v: 'exo-2-{r}-wght-normal', vi: 'exo-2-{r}-wght-italic', weight: '100 900' },
  'Roboto Condensed': { s: { 400: 'roboto-condensed-{r}-400-normal', 600: 'roboto-condensed-{r}-600-normal', 700: 'roboto-condensed-{r}-700-normal', 800: 'roboto-condensed-{r}-800-normal' }, si: { 700: 'roboto-condensed-{r}-700-italic', 800: 'roboto-condensed-{r}-800-italic' } },
  'Roboto Slab': { v: 'roboto-slab-{r}-wght-normal', weight: '100 900' },
  'PT Sans Narrow': { s: { 400: 'pt-sans-narrow-{r}-400-normal', 700: 'pt-sans-narrow-{r}-700-normal' } },
  'Source Sans 3': { v: 'source-sans-3-{r}-wght-normal', weight: '200 900' },
};

const DIRS = { film: path.join(FILM, 'fonts'), bannery: path.join(ROOT, 'assets/fonts') };
const listCache = {};
const files = (dir) => (listCache[dir] ||= new Set(fs.existsSync(DIRS[dir]) ? fs.readdirSync(DIRS[dir]) : []));

// @font-face CSS; urlOf(absPath) → URL served by the render server
export function fontCss(urlOf, extra = {}) {
  const all = { ...FONTS, ...extra }, out = [], missing = [];
  const face = (fam, F, stem, weight, style) => {
    for (const [r, range] of [['latin', LATIN], ['latin-ext', EXT]]) {
      const f = `${stem.replace('{r}', r)}.woff2`, dir = F.dir || 'film';
      if (!files(dir).has(f)) { missing.push(f); continue; }
      out.push(`@font-face{font-family:'${fam}';font-style:${style};font-weight:${weight};${F.stretch ? `font-stretch:${F.stretch};` : ''}font-display:block;src:url(${urlOf(path.join(DIRS[dir], f))}) format('woff2');unicode-range:${range};}`);
    }
  };
  for (const [fam, F] of Object.entries(all)) {
    if (F.v) face(fam, F, F.v, F.weight, 'normal');
    if (F.vi) face(fam, F, F.vi, F.weight, 'italic');
    for (const [w, stem] of Object.entries(F.s || {})) face(fam, F, stem, w, 'normal');
    for (const [w, stem] of Object.entries(F.si || {})) face(fam, F, stem, w, 'italic');
  }
  return { css: out.join('\n'), missing };
}
